+  if (status != ZX_OK) {
+    printf("failed to copy payload (%d); will not crash.\n", status);
+    return -1;
+  }
+
+  status = mem->CommitAndMap(kUserMemorySize, /* offset */ 0);
+  if (status != ZX_OK) {
