+  ~HandleTable();
+
+  HandleTable(const HandleTable&) = delete;
+  HandleTable(HandleTable&&) = delete;
+
+  HandleTable& operator=(const HandleTable&) = delete;
+  HandleTable& operator=(HandleTable&&) = delete;
