+static const struct argp_option options[] = {
+  {"host-priv-port",	'h', "PORT", 0, "Host private port PORT"},
+  {"device-master-port",'d', "PORT", 0, "Device master port PORT"},
+  {"next-task",		'N', "TASK", 0, "Next bootstrap task TASK"},
+  {0}
+};
