+/* Return 1 if pid is in use by a zombie. */
+int
+zombie_check_pid (pid_t pid)
+{
+  struct zombie *z;
+  for (z = zombie_list; z; z = z->next)
+    if (z->pid == pid || -z->pid == pid)
+      return 1;
+  return 0;
+}
