+/* Implement proc_setsid as described in <hurd/proc.defs>. */
+error_t
+S_proc_setsid (struct proc *p)
+{
+  struct session *sess;
+  
+  if (p->p_pgrp->pg_pgid == p->p_pid || pgrp_find (p->p_pid))
+    return EPERM;
+  
+  leave_pgrp (p);
+  
+  sess = new_session (p);
+  p->p_pgrp= new_pgrp (p->p_pid, sess);
+  join_pgrp (p);
+
+  return 0;
+}
