+ loop:
+  if (class->flags & PORT_CLASS_NO_ALLOC)
+   { 
+     class->flags |= PORT_CLASS_ALLOC_WAIT;
+     condition_wait (&_ports_block, &_ports_lock);
+     goto loop;
+   }
