+  sav = inl (0xCF8);
+  outl (0x80000000 | (bus << 16) | (dev << 11) | (func << 8) | (reg & ~3),
+	0xCF8);
+  /* NOTE: x86 is already LE */
+  switch (size)
+    {
+    case 1:
