+/* Add to the end of the queue */
+static void
+enqueue (struct pbufqueue *q, struct pbuf *p)
+{
+  *(q->tail) = p;
+  p->next = 0;
+  q->tail = &p->next;
+
+  q->len++;
+}
+
+/* Get from the head of the queue */
+static struct pbuf *
+dequeue (struct pbufqueue *q)
+{
+  struct pbuf *ret;
+
+  if (!q->head)
+    return 0;
+
+  ret = q->head;
+  q->head = q->head->next;
+  ret->next = 0;
+  q->len--;
+
+  if (!q->head)
+    q->tail = &q->head;
+
+  return ret;
+}
