+{
+  error_t err = 0;
+  struct netif *netif;
+
+  if (!user)
+    return EOPNOTSUPP;
+
+  netif = get_if (ifnam);
+
+  if (!user->isroot)
+    err = EPERM;
+  else if (!netif)
+    err = ENODEV;
+  else
+    err = if_change_flags (netif, flags);
+
+  return err;
+}
+
+/* 17 SIOCGIFFLAGS -- Get flags of a network interface.  */
+kern_return_t
+lwip_S_iioctl_siocgifflags (struct sock_user * user, char *name, short *flags)
