+#define MINUTE	60
+#define HOUR	(MINUTE * 60)
+#define DAY	(HOUR * 24)
+#define WEEK	(DAY * 7)
+#define MONTH	(DAY * 30)
+#define YEAR	(DAY * 355)
+
+const char *
+timeprt(time_t now, time_t seconds, int space)
+{
+	time_t years, months, weeks, days, hours, minutes;
+	static char buf[20];
+
+	if (now > seconds)
+		return ("none");
+
+	seconds -= now;
+
+	minutes = (seconds + MINUTE / 2) / MINUTE;
+	hours = (seconds + HOUR / 2) / HOUR;
+	days = (seconds + DAY / 2) / DAY;
+	years = (seconds + YEAR / 2) / YEAR;
+	months = (seconds + MONTH / 2) / MONTH;
+	weeks = (seconds + WEEK / 2) / WEEK;
+
+	if (years >= 2) {
+		(void)snprintf(buf, space+1, "%" PRId64 "years", years);
+		return buf;
+	}
+	if (weeks > 9) {
+		(void)snprintf(buf, space+1, "%" PRId64 "months", months);
+		return buf;
+	}
+	if (days > 9) {
+		(void)snprintf(buf, space+1, "%" PRId64 "weeks", weeks);
+		return buf;
+	}
+	if (hours > 36) {
+		(void)snprintf(buf, space+1, "%" PRId64 "days", days);
+		return buf;
+	}
+	if (minutes > 60) {
+		(void)snprintf(buf, space+1, "%2d:%d",
+		    (int)(minutes / 60), (int)(minutes % 60));
+		return buf;
+	}
+	(void)snprintf(buf, sizeof buf, "%2d", (int)minutes);
+	return buf;
+}
+
+/*
+ * Calculate the grace period and return a precise string for it,
+ * either in seconds or in format xWyDzHtMuS
+ */
+const char *
+timepprt(time_t seconds, int hflag, int space)
+{
+	static char buf[20], *append;
+	int i, remain = space + 1;
+
+	if (hflag == 0) {
+		snprintf(buf, remain, "%" PRId64, seconds);
+		return buf;
+	}
+
+	append = &buf[0];
+	if ((seconds / WEEK) > 0) {
+		i = snprintf(append, remain, "%" PRId64 "W", (seconds / WEEK));
+		append += i;
+		remain -=i;
+		seconds = seconds % WEEK;
+	}
+	if (remain < 3 || seconds == 0)
+		return (buf);
+	if ((seconds / DAY) > 0) {
+		i = snprintf(append, remain, "%" PRId64 "D", (seconds / DAY));
+		append += i;
+		remain -=i;
+		seconds = seconds % DAY;
+	}
+	if (remain < 4 || seconds == 0)
+		return (buf);
+	if ((seconds / HOUR) > 0) {
+		i = snprintf(append, remain, "%" PRId64 "H", (seconds / HOUR));
+		append += i;
+		remain -=i;
+		seconds = seconds % HOUR;
+	}
+	if (remain < 4 || seconds == 0)
+		return (buf);
+	if ((seconds / MINUTE) > 0) {
+		i = snprintf(append, remain, "%" PRId64 "M",
+		    (seconds / MINUTE));
+		append += i;
+		remain -=i;
+		seconds = seconds % MINUTE;
+	}
+	if (remain < 4 || seconds == 0)
+		return (buf);
+	i = snprintf(append, remain, "%" PRId64 "S", seconds);
+	return (buf);
+}
+
+/*
+ * convert a string of the form xWyDzHtMuS, or plain decimal, to 
+ * a time in seconds
+ */
+int
+timeprd(const char *str, time_t *valp)
+{
+	char buf[20];
+	char *cur, *next, *end;
+	time_t val= 0;
+
+	strncpy(buf, str, sizeof(buf));
+	next = buf;
+	cur = strsep(&next, "Ww");
+	if (next != NULL) {
+		val = strtoumax(cur, &end, 10) * WEEK;	
+		if (end[0] != '\0')
+			return EINVAL;
+	} else
+		next = cur;
+	cur = strsep(&next, "Dd");
+	if (next != NULL) {
+		val += strtoumax(cur, &end, 10) * DAY;	
+		if (end[0] != '\0')
+			return EINVAL;
+	} else
+		next = cur;
+	cur = strsep(&next, "Hh");
+	if (next != NULL) {
+		val += strtoumax(cur, &end, 10) * HOUR;	
+		if (end[0] != '\0')
+			return EINVAL;
+	} else
+		next = cur;
+	cur = strsep(&next, "Mm");
+	if (next != NULL) {
+		val += strtoumax(cur, &end, 10) * MINUTE;	
+		if (end[0] != '\0')
+			return EINVAL;
+	} else
+		next = cur;
+	cur = strsep(&next, "Ss");
+	val += strtoumax(cur, &end, 10);
+	if (end[0] != '\0')
+		return EINVAL;
+	*valp = val;
+	return 0;
+}
+
+/*
+ * convert a string to a uint64 value
+ */
+int
+intrd(char *str, uint64_t *val, u_int flags)
+{
+	char *last = &str[strlen(str) - 1];
+	int ret;
+
+	if (*last >= '0' && *last <= '9') {
+		/* no unit provided, use default */
+		errno = 0;
+		*val = strtoumax(str, NULL, 10);
+		if (flags & HN_B) {
+			/* in kb, convert to disk blocks */
+			*val = btodb(*val * 1024);
+		}
+		
+		return errno;
+	}
+	if (strcmp(str, "-") == 0 || strcmp(str, "unlimited") == 0) {
+		*val = UQUAD_MAX;
+		return 0;
+	}
+	if (flags & HN_B) {
+		if (*last == 'B' || *last == 'b')
+			*last = '\0';
+	}
+	ret = dehumanize_number(str, (int64_t *)val);
+	if (flags & HN_B)
+		*val = btodb(*val);
+	return ret;
+}

