+		error = ENOMEM;
+		if (!quota2_prop_add_command(cmds, "get version",
+		    quotatypes[q1cmd & SUBCMDMASK], datas))
+			goto out_cmds;
+		if (!prop_dictionary_set_and_rel(dict, "commands", cmds))
+			goto out_dict;
+		error = VFS_QUOTACTL(mp, dict);
+		if (error)
+			goto out_dict;
+		if ((error = quota2_get_cmds(dict, &cmds)) != 0)
+			goto out_dict;
+		cmd = prop_array_get(cmds, 0);
+		if (cmd == NULL) {
+			error = EINVAL;
+			goto out_dict;
+		}
+		if (!prop_dictionary_get_int8(cmd, "return", &error8)) {
+			error = EINVAL;
+			goto out_dict;
+		}
+		error = error8;
+		goto out_dict;
+
+	case Q_SETUSE:
+	default:
+		error = EOPNOTSUPP;
+		goto out_datas;
+	}
+out_data:
+	prop_object_release(data);
+out_datas:
+	prop_object_release(datas);
+out_cmds:
+	prop_object_release(cmds);
+out_dict:
+	prop_object_release(dict);
+out:
+	vrele(vp);
+	return error;
+}

