+		ret.orig = (msan_orig_t *)msan_dummy_orig;
+	} else {
+		ret.shad = (void *)kmsan_md_addr_to_shad(addr);
+		ret.orig = (msan_orig_t *)kmsan_md_addr_to_orig(addr);
+		ret.orig = (msan_orig_t *)((uintptr_t)ret.orig & ~0x3);
+	}
