+static void
+simple_test_waiter_lwp(void *arg)
+{
+	struct lwp_data *d = arg;
+
+	d->threadid = _lwp_self();
+
+	atomic_inc_uint(&nlwps_running);
+	membar_sync();
+
+	if (__futex(d->futex_ptr, d->wait_op | d->op_flags,
