+		membar_sync();
+		sleep(1);
+	} while (LOAD(d->futex_ptr) != 0);
+
+	STORE(d->futex_ptr, 2);
+	membar_sync();
+
+	do {
+		membar_sync();
+		sleep(1);
+	} while (LOAD(d->futex_ptr) != 3);

