+	sprintf(buf, "panic: %s\n", fmt);
+	kprintf(buf, TOCONS | TOLOG, NULL, ap);
+	va_end(ap);
+
+#ifdef KGDB
+	kgdb_panic();
+#endif
+#ifdef KADB
+	if (boothowto & RB_KDB) {
+		int s;
+
+		s = splnet();	/* below kdb pri */
+		setsoftkdb();
+		splx(s);
+	}
+#endif
+#ifdef DDB
+	Debugger();
+#else
+#ifdef PANICWAIT
+	printf("hit any key to boot/dump...\n>");
+	cngetc();
+#endif
+#endif
