+/*
+ * System calls relating to loadable modules.
+ */
+
+#include <sys/cdefs.h>
+__KERNEL_RCSID(0, "$NetBSD: sys_module.c,v 1.1 2008/01/16 12:34:51 ad Exp $");
+
+#include <sys/param.h>
+#include <sys/systm.h>
+#include <sys/proc.h>
+#include <sys/kauth.h>
+#include <sys/kobj.h>
+#include <sys/kmem.h>
+#include <sys/module.h>
+#include <sys/kauth.h>
+#include <sys/syscall.h>
+#include <sys/syscallargs.h>
+
+int
+sys_modctl(struct lwp *l, const struct sys_modctl_args *uap,
+	   register_t *retval)
+{
+	/* {
+		syscallarg(int)		cmd;
+		syscallarg(void *)	arg;
+	} */
+	char buf[MAXMODNAME];
+	size_t mslen;
+	module_t *mod;
+	modinfo_t *mi;
+	modstat_t *ms, *mso;
+	vaddr_t addr;
+	size_t size;
+	struct iovec iov;
+	int error;
+	void *arg;
+
+	arg = SCARG(uap, arg);
+
+	switch (SCARG(uap, cmd)) {
+	case MODCTL_LOAD:
+	case MODCTL_FORCELOAD:
+	case MODCTL_UNLOAD:
+		/* Authorize. */
+		error = kauth_authorize_system(l->l_cred, KAUTH_SYSTEM_MODULE,
+		    0, (void *)SCARG(uap, cmd), NULL, NULL);
+		if (error != 0) {
+			return error;
+		}
+		break;
+	default:
+		break;
+	}
+
+	switch (SCARG(uap, cmd)) {
+	case MODCTL_FORCELOAD:
+	case MODCTL_LOAD:
+		error = copyinstr(arg, buf, sizeof(buf) - 1, NULL);
+		if (error == 0) {
+			error = module_load(buf,
+			    SCARG(uap, cmd) == MODCTL_FORCELOAD);
+		}
+		break;
+
+	case MODCTL_UNLOAD:
+		error = copyinstr(arg, buf, sizeof(buf) - 1, NULL);
+		if (error == 0) {
+			error = module_unload(buf);
+		}
+		break;
+
+	case MODCTL_STAT:
+		error = copyin(arg, &iov, sizeof(iov));
+		if (error != 0) {
+			break;
+		}
+		mutex_enter(&module_lock);
+		mslen = (module_count + 1) * sizeof(modstat_t);
+		mso = kmem_zalloc(mslen, KM_SLEEP);
+		if (mso == NULL) {
+			mutex_exit(&module_lock);
+			return ENOMEM;
+		}
+		ms = mso;
+		TAILQ_FOREACH(mod, &module_list, mod_chain) {
+			mi = mod->mod_info;
+			strlcpy(ms->ms_name, mi->mi_name, sizeof(ms->ms_name));
+			if (mi->mi_required != NULL) {
+				strlcpy(ms->ms_required, mi->mi_required,
+				    sizeof(ms->ms_required));
+			}
+			if (mod->mod_kobj != NULL) {
+				kobj_stat(mod->mod_kobj, &addr, &size);
+				ms->ms_addr = addr;
+				ms->ms_size = size;
+			}
+			ms->ms_class = mi->mi_class;
+			ms->ms_refcnt = mod->mod_refcnt;
+			ms->ms_source = mod->mod_source;
+			ms++;
+		}
+		mutex_exit(&module_lock);
+		error = copyout(mso, iov.iov_base,
+		    min(mslen - sizeof(modstat_t), iov.iov_len));
+		kmem_free(mso, mslen);
+		if (error == 0) {
+			iov.iov_len = mslen - sizeof(modstat_t);
+			error = copyout(&iov, arg, sizeof(iov));
+		}
+		break;
+
+	default:
+		error = EINVAL;
+		break;
+	}
+
+	return error;
+}

