+	sd->sd_lobase = (uint64_t)base;
+	sd->sd_type = type;
+	sd->sd_dpl = dpl;
+	sd->sd_p = 1;
+	sd->sd_hilimit = (unsigned)limit >> 16;
+	sd->sd_gran = gran;
+	sd->sd_hibase = (uint64_t)base >> 24;
