-static int
-gtmr_match(device_t parent, cfdata_t cf, void *aux)
-{
-	struct mainbus_attach_args * const mba = aux;
-
-	if (gtmr_sc.sc_dev != NULL)
-		return 0;
-
-	if (strcmp(mba->mba_name, cf->cf_name) != 0)
-		return 0;
-
-	return 1;
-}
