+{
+	struct unvname *ret = malloc(sizeof(struct unvname), M_PROC, M_WAITOK);
+	ret->un_name = malloc(size, M_PROC, M_WAITOK);
+	memcpy(ret->un_name, name, size);
+	ret->un_namesize = size;
+	ret->un_flags = flags;
+	return ret;
