+#include <sys/types.h>
+#include <sys/systm.h>
+
+/*
+ * The POISON is used as known text to copy into free objects so
+ * that modifications after frees can be detected.
+ */
+#ifdef DEADBEEF0
+#define POISON	((unsigned) DEADBEEF0)
+#else
+#define POISON	((unsigned) 0xdeadbeef)
+#endif
+#define POISON_SIZE	32
+
+void
+poison_mem(void *v, size_t len)
+{
+	uint32_t *ip = v;
+	size_t i;
+
+	if (len > POISON_SIZE)
+		len = POISON_SIZE;
+	len = len / sizeof(*ip);
+	for (i = 0; i < len; i++)
+		ip[i] = POISON;
+}
+
+int
+poison_check(void *v, size_t len, size_t *pidx, int *pval)
+{
+
+	uint32_t *ip = v;
+	size_t i;
+
+	if (len > POISON_SIZE)
+		len = POISON_SIZE;
+	len = len / sizeof(*ip);
+	for (i = 0; i < len; i++) {
+		if (ip[i] != POISON) {
+			*pidx = i;
+			*pval = ip[i];
+			return 1;
+		}
+	}
