+use crate::{
+    context::{self, ContextId, Status},
+    ptrace
+};
+
+use alloc::collections::{BTreeMap, BTreeSet};
+use core::{
+    cmp,
+    mem,
+    slice,
+    sync::atomic::{AtomicUsize, Ordering}
+};
+use spin::{Mutex, RwLock};
+use syscall::{
+    data::{IntRegisters, FloatRegisters},
+    error::*,
+    flag::*,
+    scheme::Scheme
+};
+
+#[derive(Clone, Copy)]
+enum RegsKind {
+    Float,
+    Int
+}
+#[derive(Clone, Copy)]
+enum Operation {
+    Memory,
+    Regs(RegsKind),
+    Trace
+}
+
+#[derive(Clone, Copy)]
+struct Handle {
+    flags: usize,
+    pid: ContextId,
+    operation: Operation
+}
+
+pub struct ProcScheme {
+    next_id: AtomicUsize,
+    handles: RwLock<BTreeMap<usize, Handle>>,
+    traced: Mutex<BTreeSet<ContextId>>
+}
+
+impl ProcScheme {
+    pub fn new() -> Self {
+        Self {
+            next_id: AtomicUsize::new(0),
+            handles: RwLock::new(BTreeMap::new()),
+            traced: Mutex::new(BTreeSet::new())
+        }
+    }
+}
+
+impl Scheme for ProcScheme {
+    fn open(&self, path: &[u8], flags: usize, uid: u32, gid: u32) -> Result<usize> {
+        let path = core::str::from_utf8(path).map_err(|_| Error::new(EINVAL))?;
+        let mut parts = path.splitn(2, '/');
+        let pid = parts.next()
+            .and_then(|s| s.parse().ok())
+            .map(ContextId::from)
+            .ok_or(Error::new(EINVAL))?;
+        let operation = match parts.next() {
