+
+static BREAKPOINTS: Once<RwLock<BTreeMap<ContextId, Handle>>> = Once::new();
+
+fn init_breakpoints() -> RwLock<BTreeMap<ContextId, Handle>> {
+    RwLock::new(BTreeMap::new())
