+static struct k_sem isr_sync;
+static struct k_timer isr_timer;
+
+static void isr_notify(struct k_timer *timer)
+{
+	struct transit_state *tsp = k_timer_user_data_get(timer);
+
+	TC_PRINT("ISR NOTIFY %s %d\n", tsp->tag, k_is_in_isr());
+	notify(tsp);
+	k_sem_give(&isr_sync);
