+	}
+
+	k_spin_unlock(&srv->lock, key);
+
+	if (start) {
+		__ASSERT_NO_MSG(srv->start != NULL);
+		srv->start(srv, onoff_start_notify);
+	} else if (notify) {
+		notify_one(srv, cli, 0);
+	}
+
+	return rv;
+}
